// Optional and disabled by default to preserve administrator findings.
MATCH (admin:SCCM_AdminUser)
MATCH (admin)-[assignment:SCCM_IsAssigned]->(role:SCCM_SecurityRole)
// Supported built-in roles with potential device control.
WHERE role.roleID IN [
// Full Administrator: deploys software.
  'SMS0001R',
// Application Author: edits deployed applications; deployment is not checked.
  'SMS0008R',
// Application Administrator: creates and deploys applications.
  'SMS0009R',
// Compliance Settings Manager: runs scripts through baselines.
  'SMS0006R',
// OS Deployment Manager: runs commands through task sequences.
  'SMS000AR',
// Operations Administrator: deploys software.
  'SMS000ER',
// Security Administrator: can delegate Full Administrator.
  'SMS000FR'
]
// SMS00001 = All Systems. All Users and All security scope are not required.
  AND 'SMS00001' IN assignment.collectionIds
// Require all assignments to belong to the same hierarchy.
  AND role.environmentid = admin.environmentid
// Classify only the SCCM record; mapped AD identities remain separate.
WITH admin AS n
RETURN DISTINCT n
